import{_ as o,C as r,o as t,c as i,a2 as s,b as l,w as n,a as d,E as c,a3 as u}from"./chunks/framework.Brv5O9VI.js";const _=JSON.parse('{"title":"14.7 Messaging, Queues & Asynchronous Processing","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.7-messaging-and-queues.md","filePath":"system-design/14.7-messaging-and-queues.md"}'),g={name:"system-design/14.7-messaging-and-queues.md"};function h(p,e,f,m,y,b){const a=r("Mermaid");return t(),i("div",null,[e[1]||(e[1]=s('<h1 id="_14-7-messaging-queues-asynchronous-processing" tabindex="-1">14.7 Messaging, Queues &amp; Asynchronous Processing <a class="header-anchor" href="#_14-7-messaging-queues-asynchronous-processing" aria-label="Permalink to &quot;14.7 Messaging, Queues &amp; Asynchronous Processing&quot;">​</a></h1><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Message queues and asynchronous task workers decouple long-running, compute-heavy jobs (like web scraping, bulk document indexing, or PDF report rendering) from synchronous HTTP request-response cycles, preventing web servers from timing out.</p><hr><h2 id="_2-how-this-project-uses-it" tabindex="-1">2. How THIS Project Uses It <a class="header-anchor" href="#_2-how-this-project-uses-it" aria-label="Permalink to &quot;2. How THIS Project Uses It&quot;">​</a></h2><ul><li><strong>Synchronous Execution</strong>: The current request pipeline in [<code>app.py</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py) executes <strong>synchronously</strong> within the request handler because inference completes in under 18ms.</li><li><strong>Offline Batch Processing</strong>: Heavy tasks like bulk corpus merging and FAISS index rebuilding are executed offline via standalone Python scripts ([<code>bulk_ingest.py</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/bulk_ingest.py), [<code>merge_corpus.py</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/merge_corpus.py), [<code>rebuild_faiss_index.py</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/rebuild_faiss_index.py)).</li><li><strong>Queues (Kafka / RabbitMQ / Celery)</strong>: <strong>Not Used</strong>. Given sub-20ms latencies, integrating an external message broker would add unnecessary infrastructure complexity [CONFIRM WITH DEVELOPER].</li></ul>',6)),(t(),l(u,null,{default:n(()=>[c(a,{id:"mermaid-30",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20SynchronousFlow%5B%22Current%20Synchronous%20Model%20(%3C18ms)%22%5D%0A%20%20%20%20%20%20%20%20User%5B%22User%20HTTP%20Request%22%5D%20--%3E%20API%5B%22FastAPI%20Handler%22%5D%0A%20%20%20%20%20%20%20%20API%20--%3E%20FastEmbed%5B%22In-Memory%20FastEmbed%20%26%20FAISS%22%5D%0A%20%20%20%20%20%20%20%20FastEmbed%20--%3E%20Resp%5B%22Instant%20HTTP%20Response%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20ProposedAsyncFlow%5B%22Future%20Scale%3A%20Async%20Bulk%20Ingestion%20Queue%22%5D%0A%20%20%20%20%20%20%20%20Admin%5B%22Admin%20Portal%20Batch%20Upload%22%5D%20--%3E%20API2%5B%22FastAPI%20%2Fjobs%2Fingest%22%5D%0A%20%20%20%20%20%20%20%20API2%20--%3E%20Queue%5B%22Redis%20Streams%20%2F%20Celery%20Queue%22%5D%0A%20%20%20%20%20%20%20%20Queue%20--%3E%20Worker%5B%22Background%20Celery%20Worker%20(ONNX%20Embedder)%22%5D%0A%20%20%20%20%20%20%20%20Worker%20--%3E%20S3%5B%22Write%20New%20Index%20to%20Object%20Storage%22%5D%0A%20%20%20%20%20%20%20%20Worker%20--%3E%20Event%5B%22Emit%20Ingestion%20Complete%20Event%22%5D%0A%20%20%20%20end%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s('<hr><h2 id="_3-comparison-with-messaging-alternatives" tabindex="-1">3. Comparison with Messaging Alternatives <a class="header-anchor" href="#_3-comparison-with-messaging-alternatives" aria-label="Permalink to &quot;3. Comparison with Messaging Alternatives&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Technology</th><th style="text-align:left;">Paradigm</th><th style="text-align:left;">Latency Overhead</th><th style="text-align:left;">Delivery Guarantees</th><th style="text-align:left;">Ordering</th><th style="text-align:left;">Fit for This Engine</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Direct Synchronous</strong> (Used)</td><td style="text-align:left;">Request-Response</td><td style="text-align:left;"><strong>0.00 ms</strong></td><td style="text-align:left;">Exact (In-thread)</td><td style="text-align:left;">Strict</td><td style="text-align:left;"><strong>Optimal for &lt;20ms inference</strong></td></tr><tr><td style="text-align:left;"><strong>Celery + Redis</strong></td><td style="text-align:left;">Task Queue</td><td style="text-align:left;">~10 - 25 ms</td><td style="text-align:left;">At-least-once</td><td style="text-align:left;">FIFO per queue</td><td style="text-align:left;">Best for future bulk file OCR</td></tr><tr><td style="text-align:left;"><strong>RabbitMQ</strong></td><td style="text-align:left;">Message Broker</td><td style="text-align:left;">~3 - 8 ms</td><td style="text-align:left;">At-least-once / AMQP</td><td style="text-align:left;">Strict FIFO</td><td style="text-align:left;">Overkill for simple tasks</td></tr><tr><td style="text-align:left;"><strong>Apache Kafka</strong></td><td style="text-align:left;">Distributed Event Log</td><td style="text-align:left;">~15 - 40 ms</td><td style="text-align:left;">Exactly-once (Transactional)</td><td style="text-align:left;">Partition Order</td><td style="text-align:left;">Extreme overkill</td></tr></tbody></table><hr><h2 id="_4-trade-offs-accepted" tabindex="-1">4. Trade-offs Accepted <a class="header-anchor" href="#_4-trade-offs-accepted" aria-label="Permalink to &quot;4. Trade-offs Accepted&quot;">​</a></h2><ul><li><strong>Coupled Ingestion</strong>: Adding 5,000 new standards cannot be done through the live REST API without momentarily blocking CPU threads; it requires running <code>rebuild_faiss_index.py</code> offline and reloading the container.</li></ul><hr><h2 id="_5-what-breaks-at-scale" tabindex="-1">5. What Breaks at Scale <a class="header-anchor" href="#_5-what-breaks-at-scale" aria-label="Permalink to &quot;5. What Breaks at Scale&quot;">​</a></h2><ul><li><strong>At 10x Load</strong>: Synchronous processing handles the load cleanly without queueing.</li><li><strong>At 100x Load</strong>: If large batch CSV exports (10,000 rows) or multi-megabyte PDF certificate uploads are added, the synchronous HTTP thread pool will starve.</li><li><strong>At 1000x Load</strong>: Any heavy background task execution inside the web process causes catastrophic HTTP request dropouts.</li></ul><hr><h2 id="_6-how-a-senior-engineer-would-improve-it" tabindex="-1">6. How a Senior Engineer Would Improve It <a class="header-anchor" href="#_6-how-a-senior-engineer-would-improve-it" aria-label="Permalink to &quot;6. How a Senior Engineer Would Improve It&quot;">​</a></h2><p>Introduce <strong>Celery with Redis</strong> for asynchronous job offloading:</p><ul><li>The user uploads a 50-page PDF audit dossier.</li><li>API instantly responds with <code>202 Accepted</code> and a <code>job_id</code>.</li><li>Background Celery workers execute OCR and vector extraction.</li><li>Client polls <code>GET /jobs/{id}</code> or receives a WebSocket completion notification.</li></ul><hr><h2 id="_7-30-second-spoken-answer" tabindex="-1">7. 30-Second Spoken Answer <a class="header-anchor" href="#_7-30-second-spoken-answer" aria-label="Permalink to &quot;7. 30-Second Spoken Answer&quot;">​</a></h2><blockquote><p>&quot;We intentionally omitted message queues like Celery or Kafka because our end-to-end inference completes in under eighteen milliseconds, well below standard web timeouts. Adding a message queue would introduce unnecessary polling complexity for users; however, if we introduce heavy OCR parsing of fifty-page audit PDFs in the future, we would offload that processing to Celery workers over Redis.&quot;</p></blockquote>',16))])}const A=o(g,[["render",h]]);export{_ as __pageData,A as default};
